{
	"name": "hevy-mcp",
	"version": "6.1.18",
	"private": false,
	"description": "A Model Context Protocol (MCP) server implementation that interfaces with the Hevy fitness tracking app and its API.",
	"repository": {
		"type": "git",
		"url": "https://github.com/chrisdoc/hevy-mcp"
	},
	"bin": {
		"hevy-mcp": "dist/cli.mjs"
	},
	"files": [
		"dist",
		"README.md",
		"server.json"
	],
	"type": "module",
	"main": "dist/index.mjs",
	"types": "dist/index.d.mts",
	"exports": {
		".": {
			"types": "./dist/index.d.mts",
			"import": "./dist/index.mjs"
		}
	},
	"publishConfig": {
		"access": "public"
	},
	"scripts": {
		"build": "tsdown -c tsdown.config.ts",
		"prepack": "node ../../scripts/server-manifest.mjs check && pnpm run build",
		"check:types": "tsc --noEmit -p tsconfig.json",
		"build:standalone": "cross-env HEVY_MCP_BUILD_MODE=standalone tsdown -c tsdown.config.ts"
	},
	"dependencies": {
		"@effect/opentelemetry": "4.0.0-rc.117",
		"@modelcontextprotocol/node": "^2.0.0",
		"@modelcontextprotocol/server": "^2.0.0",
		"@opentelemetry/api": "^1.9.1",
		"@opentelemetry/exporter-metrics-otlp-http": "^0.222.0",
		"@opentelemetry/exporter-trace-otlp-http": "^0.222.0",
		"@opentelemetry/resources": "^2.11.0",
		"@opentelemetry/sdk-metrics": "^2.11.0",
		"@opentelemetry/sdk-trace-base": "^2.11.0",
		"@opentelemetry/sdk-trace-node": "^2.11.0",
		"@sentry/node": "^10.75.0",
		"effect": "^4.0.0-rc.117",
		"semver": "^7.8.5",
		"zod": "^4.6.5"
	},
	"devDependencies": {
		"@hevy-mcp/core": "workspace:*",
		"@hevy-mcp/hevy-client": "workspace:*",
		"@sentry/core": "^10.75.0",
		"@types/node": "^26.6.2",
		"cross-env": "^10.1.0",
		"tsdown": "^0.23.0",
		"typescript": "^7.0.2"
	},
	"engines": {
		"node": ">=20.0.0"
	},
	"mcpName": "io.github.chrisdoc/hevy-mcp"
}

{
	"name": "@hevy-mcp/worker",
	"version": "0.3.2",
	"private": true,
	"type": "module",
	"exports": {
		".": {
			"types": "./src/index.ts",
			"import": "./src/index.ts"
		}
	},
	"scripts": {
		"build": "tsc --noEmit -p tsconfig.json",
		"check:types": "tsc --noEmit -p tsconfig.json"
	},
	"dependencies": {
		"@cloudflare/workers-oauth-provider": "^1.2.1",
		"@modelcontextprotocol/server": "^2.0.0",
		"effect": "^4.0.0-rc.117",
		"zod": "^4.6.5"
	},
	"devDependencies": {
		"@hevy-mcp/core": "workspace:*",
		"@hevy-mcp/hevy-client": "workspace:*"
	}
}

{
	"version": 1,
	"workspaceGlob": "packages/*",
	"root": {
		"private": true,
		"orchestrator": true
	},
	"workspaces": [
		{
			"id": "hevy-client",
			"path": "packages/hevy-client",
			"name": "@hevy-mcp/hevy-client",
			"private": true,
			"publishable": false,
			"runtime": "neutral",
			"exports": [".", "./types", "./schemas", "./internal"],
			"dependencies": [],
			"boundary": {
				"allowed": {},
				"forbidden": [
					"@cloudflare/",
					"cloudflare:",
					"@sentry/",
					"@opentelemetry/"
				],
				"rejectBuiltins": true,
				"rejectDynamicImports": true
			},
			"artifacts": ["generated-client", "hevy-client-package"],
			"role": "client"
		},
		{
			"id": "operations",
			"path": "packages/operations",
			"name": "@hevy-mcp/operations",
			"private": true,
			"publishable": false,
			"runtime": "neutral",
			"exports": [".", "./schemas"],
			"dependencies": ["hevy-client"],
			"boundary": {
				"allowed": {
					"@hevy-mcp/hevy-client": ["", "types", "internal"]
				},
				"forbidden": [
					"@cloudflare/",
					"cloudflare:",
					"@sentry/",
					"@opentelemetry/"
				],
				"rejectBuiltins": true,
				"rejectDynamicImports": true
			},
			"artifacts": ["operations-source"],
			"role": "runtime"
		},
		{
			"id": "core",
			"path": "packages/core",
			"name": "@hevy-mcp/core",
			"private": true,
			"publishable": false,
			"runtime": "neutral",
			"exports": ["."],
			"dependencies": ["hevy-client", "operations"],
			"boundary": {
				"allowed": {
					"@hevy-mcp/hevy-client": ["", "types", "schemas"],
					"@hevy-mcp/operations": ["", "schemas"]
				},
				"forbidden": [
					"@cloudflare/",
					"cloudflare:",
					"@sentry/",
					"@opentelemetry/"
				],
				"rejectBuiltins": true,
				"rejectDynamicImports": true
			},
			"artifacts": ["core-package"],
			"role": "runtime"
		},
		{
			"id": "node",
			"path": "packages/node",
			"name": "hevy-mcp",
			"private": false,
			"publishable": true,
			"runtime": "node",
			"exports": ["."],
			"dependencies": ["hevy-client", "core"],
			"boundary": {
				"allowed": {
					"@hevy-mcp/core": [""],
					"@hevy-mcp/hevy-client": [""]
				},
				"forbidden": ["@cloudflare/", "cloudflare:"],
				"rejectBuiltins": false,
				"rejectDynamicImports": false
			},
			"artifacts": ["node-package", "docker-image"],
			"role": "server"
		},
		{
			"id": "worker",
			"path": "packages/worker",
			"name": "@hevy-mcp/worker",
			"private": true,
			"publishable": false,
			"runtime": "workerd",
			"exports": ["."],
			"dependencies": ["hevy-client", "core"],
			"boundary": {
				"allowed": {
					"@hevy-mcp/core": [""],
					"@hevy-mcp/hevy-client": ["", "internal"]
				},
				"forbidden": ["@sentry/", "@opentelemetry/"],
				"rejectBuiltins": true,
				"rejectDynamicImports": false
			},
			"artifacts": ["worker-bundle"],
			"role": "adapter"
		},
		{
			"id": "cli",
			"path": "packages/cli",
			"name": "@chrisdoc/hevy-cli",
			"private": false,
			"publishable": true,
			"runtime": "node",
			"exports": [],
			"dependencies": ["hevy-client", "operations"],
			"boundary": {
				"allowed": {
					"@hevy-mcp/hevy-client": ["", "types", "schemas"],
					"@hevy-mcp/operations": ["", "schemas"]
				},
				"forbidden": ["@cloudflare/", "cloudflare:"],
				"rejectBuiltins": false,
				"rejectDynamicImports": false
			},
			"artifacts": ["cli-package"],
			"role": "cli"
		}
	],
	"release": {
		"triggers": [
			{
				"path": "cloudflare.config.ts",
				"workspace": "worker"
			}
		],
		"bundles": [
			{
				"workspace": "hevy-client",
				"consumers": ["operations", "core", "node", "worker", "cli"]
			},
			{
				"workspace": "operations",
				"consumers": ["core", "cli"]
			},
			{
				"workspace": "core",
				"consumers": ["node", "worker"]
			}
		]
	}
}

