import { bindings, defineWorker } from "wrangler/experimental-config";
import * as entrypoint from "./packages/worker/src/worker.ts" with { type: "cf-worker" };

interface WorkerObservability {
	enabled: true;
	issues?: { enabled: boolean };
	traces?: { enabled: true; destinations: string[] };
	logs?: { enabled: true; destinations: string[] };
}

interface WorkerEnvironmentBindings {
	[key: string]:
		| ReturnType<typeof bindings.kv>
		| ReturnType<typeof bindings.text>;
	OAUTH_KV: ReturnType<typeof bindings.kv>;
}

export default defineWorker((ctx) => {
	const environment =
		process.env.WRANGLER_MODE ??
		ctx.mode ??
		process.env.CLOUDFLARE_ENV ??
		"development";
	const route = process.env.CLOUDFLARE_WORKER_ROUTE?.trim();
	const workerName =
		process.env.CLOUDFLARE_WORKER_NAME?.trim() ??
		(environment === "preview" ? "hevy-mcp-preview" : "hevy-mcp");
	const kvNamespaceId = process.env.CLOUDFLARE_OAUTH_KV_NAMESPACE_ID?.trim();
	const oauthResource = process.env.CLOUDFLARE_OAUTH_RESOURCE?.trim();
	const parseDestinations = (value: string | undefined) =>
		value
			?.split(",")
			.map((destination) => destination.trim())
			.filter(Boolean) ?? [];
	const traceDestinations = parseDestinations(
		process.env.CLOUDFLARE_OTEL_TRACES_DESTINATIONS,
	);
	const logDestinations = parseDestinations(
		process.env.CLOUDFLARE_OTEL_LOGS_DESTINATIONS,
	);
	const observability: WorkerObservability = {
		enabled: true,
		issues: { enabled: true },
	};
	if (traceDestinations.length > 0)
		observability.traces = {
			enabled: true,
			destinations: traceDestinations,
		};
	if (logDestinations.length > 0)
		observability.logs = {
			enabled: true,
			destinations: logDestinations,
		};

	const env: WorkerEnvironmentBindings = {
		OAUTH_KV: bindings.kv(kvNamespaceId ? { id: kvNamespaceId } : undefined),
	};
	if (oauthResource) env.OAUTH_RESOURCE = bindings.text(oauthResource);
	if (environment === "preview")
		env.MCP_DISABLE_ORIGIN_CHECK = bindings.text("true");
	return {
		name: workerName,
		entrypoint,
		compatibilityDate: "2026-07-11",
		compatibilityFlags: ["global_fetch_strictly_public"],
		workersDev: environment === "development",
		previewUrls: true,
		observability,
		domains: route ? [route] : undefined,
		env,
	};
});

	withCors,
	type WorkerEnv,
} from "./worker-http-helpers.js";

export {
	DEFAULT_ALLOWED_ORIGINS,
	parseAllowedOrigins,
	parseBearerApiKey,
	type WorkerEnv,
};

const MCP_PATH = "/mcp";
const HEALTH_PATH = "/health";

/**
 * Warm the tool-schema memo at module scope so the per-isolate conversion
 * cost runs during isolate warm-up instead of inside a request's billed CPU.
 * See `preloadHevyToolSchemas` in packages/core. Client requests stay within
 * the Worker CPU budget by reusing the memoized tool schemas.
 */
preloadHevyToolSchemas();

class FallbackSpan implements Span {
	get isTraced(): boolean {
		return false;
	}

	setAttribute(_key: string, _value: boolean | number | string): this {
		return this;
	}

	setAttributes(
		_attributes: Record<string, boolean | number | string | undefined>,
	): this {
		return this;
	}

	recordException(
		_exception:
			| string
			| {
					code: string | number;
					name?: string;
					message?: string;
					stack?: string;
			  }
			| {
					code?: string | number;
					name: string;
					message?: string;
					stack?: string;
			  }
			| {
					code?: string | number;
					name?: string;
					message: string;
					stack?: string;
			  },
	): void {}

	end(): void {}
}

const FALLBACK_EXECUTION_CONTEXT = {
	waitUntil(_promise: Promise<unknown>): void {},
	passThroughOnException(): void {},
	abort(_reason?: string): void {},
	exports: {},
	props: {},
	tracing: {
		enterSpan<T, A extends unknown[]>(
			_name: string,
			callback: (span: Span, ...args: A) => T,
			...args: A
		): T {
			return callback(new FallbackSpan(), ...args);
		},
		startActiveSpan<T, A extends unknown[]>(
			_name: string,
			callback: (span: Span, ...args: A) => T,
			...args: A
		): T {
			return callback(new FallbackSpan(), ...args);
		},
		startSpan(_name: string): Span {
			return new FallbackSpan();
		},
		getActiveSpan(): Span | undefined {
			return undefined;
		},
		Span: FallbackSpan,
	},
} satisfies ExecutionContext;

function requireExecutionContext(
	context: ExecutionContext | undefined,
): ExecutionContext {
	return context ?? FALLBACK_EXECUTION_CONTEXT;
}

interface WorkerDependencies {
	createValidationClient?: (apiKey: string, baseUrl: string) => HevyClient;
	createRequestClient?: (
		apiKey: string,
		baseUrl: string,
		onLog: HevyClientFactoryContext["onLog"],
	) => HevyClient;
	createServer?: (
		createClient: CreateHevyMcpServerOptions["createClient"],
		lifecycleSignal?: AbortSignal,
		executionDeadline?: number,
		observer?: CreateHevyMcpServerOptions["observer"],
		feedbackRecorder?: CreateHevyMcpServerOptions["feedbackRecorder"],
	) => Promise<McpServer>;
	createTransport?: () => WebStandardStreamableHTTPServerTransport;
	createObserver?: (
		options: WorkerToolObserverOptions,
	) => CreateHevyMcpServerOptions["observer"];
	createFeedbackRecorder?: (
		env: WorkerEnv,
	) => CreateHevyMcpServerOptions["feedbackRecorder"];
}

type ResolvedWorkerDependencies = Required<WorkerDependencies>;


